#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    ofstream out("here.txt");
    out << "{w}" << endl;
    out.close();

    ifstream in("here.txt");
    string line;
    while (getline(in, line)) {
        cout << line << endl;
    }

    ifstream missing("buzai.txt");
    if (!missing.is_open()) {
        cout << "本子没找着喵" << endl;
        return 0;
    }
    while (getline(missing, line)) {
        cout << line << endl;
    }
    return 0;
}
